def rows(topic,reserve=False):
    lines=RAW[topic].strip().splitlines()
    if len(lines)!=10:
        raise ValueError('В теме нужны десять вопросов')
    result=[]
    for i,line in enumerate(lines[5:] if reserve else lines[:5]):
        fields=line.split('|')
        if len(fields) not in (4,5):
            raise ValueError('Некорректная строка банка')
        question,answer,aliases,explanation=fields[:4]
        options=fields[4].split('~') if len(fields)==5 else []
        kind='yesno' if topic=='Да или Нет' else 'linked' if topic=='Химическая (или бытовая) загадка' else 'choice' if options else 'riddle' if (topic,i) in RIDDLES and not reserve else 'open'
        image_id=IMAGES.get(topic,'') if i==0 and not reserve else ''
        result.append(dict(topic_index=0,price=(i+1)*100,question=question,answer=answer,
            aliases=aliases.split(';') if aliases else [],explanation=explanation,
            kind='image' if image_id else kind,options=options,image_id=image_id))
        result[-1].update(copy.deepcopy(MEDIA_OVERRIDES.get((topic,reserve,i),{})))
    return validate_mixed(result,expected_count=5)


def catalog():
    # Deliberately public metadata only: no questions, options, aliases of answers or references.
    names=[*SPECIAL_TOPICS,*(name for name in RAW if name not in SPECIAL_TOPICS)]
    return [dict(name=name,aliases=ALIASES[name]) for name in names]


def presentation_pack(topics,reserve=False):
    if len(topics)!=8 or len(set(topics))!=8 or any(t not in RAW for t in topics):
        raise ValueError('Выберите восемь разных тем из каталога презентации')
    pack=[];fallback=[]
    for index,topic in enumerate(topics):
        try:
            selected=rows(topic,reserve)
        except (ValueError,KeyError,TypeError):
            selected=rows(topic,not reserve)
            fallback.append(topic)
        for q in copy.deepcopy(selected):
            q['topic_index']=index
            if q['kind']=='choice':
                random.SystemRandom().shuffle(q['options'])
            pack.append(q)
    validate_mixed(pack)
    validate_pack({'clues':pack},8)
    return pack,dict(bank_set='reserve' if reserve else 'main',fallback_topics=fallback,
                     version='2026-10-23-presentation-media-v2',reserve_requested=reserve)
